G=load()

def solve(inp):
    H,W=len(inp),len(inp[0])
    vals={x for r in inp for x in r}-{0}
    sc=max(vals,key=lambda v:sum(r.count(v) for r in inp))
    mk=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=0 and inp[r][c]!=sc]
    g=[row[:] for row in inp]
    sh=set((r,c) for r in range(H) for c in range(W) if inp[r][c]==sc)
    for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
        # collect cells along each line from shape outward; stop before marker or nonzero
        for r in range(H):
            for c in range(W):
                if (r,c) in sh:
                    rr,cc=r+dr,c+dc
                    while 0<=rr<H and 0<=cc<W and g[rr][cc]==0 and (rr,cc) not in mk:
                        g[rr][cc]=sc; rr+=dr; cc+=dc
    return g

