def f(gi):
    H=len(gi); W=len(gi[0])
    # find rectangle of color 2 (solid block)
    cells=[(i,j) for i in range(H) for j in range(W) if gi[i][j]==2]
    rs=[i for i,j in cells]; cs=[j for i,j in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    go=[[0]*W for _ in range(H)]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1): go[i][j]=2
    # noise color: any nonzero not 2
    nz=set(x for row in gi for x in row)-{2}
    ncol=nz.pop()
    for i in range(H):
        for j in range(W):
            v=gi[i][j]
            if v==ncol:
                onrect=(r0<=i<=r1 and c0<=j<=c1)
                if onrect: go[i][j]=2
                elif r0>i:
                    for j2 in range(min(j,c0),max(j,c1)+1): go[i][j2]=ncol
                elif r1<i:
                    for j2 in range(min(j,c0),max(j,c1)+1): go[i][j2]=ncol
                elif c0>j:
                    for i2 in range(min(i,r0),max(i,r1)+1): go[i2][j]=ncol
                elif c1>j:
                    for i2 in range(min(i,r0),max(i,r1)+1): go[i2][j]=ncol
    return go
