rs=[r for r in range(R) for c in range(C) if ti[r,c]==2]; cs=[c for r in range(R) for c in range(C) if ti[r,c]==2]
min_r,max_r=min(rs),max(rs); min_c,max_c=min(cs),max(cs)
for r in range(R):
    for c in range(C):
        if ti[r,c]==2: continue
        # horizontal beam: marker shares row with rect rows, beam passes through rect cols
        if min_r<=r<=max_r:
            if c<min_c: rng=range(c,min_c+1)
