            for j in rng: o[r,j]=2; continue
        # vertical beam: marker shares col with rect cols
        if min_c<=c<=max_c:
            if r<min_r: rng=range(r,min_r+1)
            elif r>max_r: rng=range(r,max_r-1,-1)
            else: continue
            for j in rng: o[j,c]=2; continue
